func renderTargetMap(v map[string][]string) string {
	parts := make([]string, 0, len(v))
	for _, k := range slices.Sorted(maps.Keys(v)) {
		e := v[k]
		parts = append(parts, k+"="+renderTargetMapValueList(e))
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

func renderTargetMapValueList(v []string) string {
	parts := make([]string, 0, len(v))
	for _, e := range v {
		parts = append(parts, e)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func renderTargetMaps(v []map[string][]string) string {
	parts := make([]string, 0, len(v))
	for _, e := range v {
		parts = append(parts, renderTargetMap(e))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func renderTargetValues(v []string) string {
	parts := make([]string, 0, len(v))
	for _, e := range v {
		parts = append(parts, e)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func renderTargets(v []Target) string {
	parts := make([]string, 0, len(v))
	for range v {
		parts = append(parts, "")
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// at extends a violation path without aliasing the parent's array.
func at(p awserr.Path, segments ...string) awserr.Path { return append(slices.Clip(p), segments...) }
